import uuid
from datetime import datetime

from sqlalchemy import UUID, DateTime, String, func, text
from sqlalchemy.orm import Mapped, mapped_column

from modules.auth.database import AuthBase

WHATSAPP_MAX_LENGTH = 16
NAME_MAX_LENGTH = 100


class User(AuthBase):
    """`users` table: docs/backend/SCHEMAS.md#users-modulesauth."""

    __tablename__ = "users"

    # The id is generated by PostgreSQL only: docs/backend/AUTH.md#user-id.
    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), primary_key=True, server_default=text("gen_random_uuid()")
    )
    whatsapp: Mapped[str] = mapped_column(String(WHATSAPP_MAX_LENGTH))
    first_name: Mapped[str] = mapped_column(String(NAME_MAX_LENGTH))
    last_name: Mapped[str] = mapped_column(String(NAME_MAX_LENGTH))
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
